<?php
if(!defined('ABSPATH'))exit;
function legacyx_reports_menu(){add_submenu_page('legacyx-firm-os','Executive Intelligence','Reports','legacyx_view_reports','legacyx-reports','legacyx_render_reports_dashboard');}add_action('admin_menu','legacyx_reports_menu',20);
function legacyx_reports_count($type){$q=wp_count_posts($type);$n=0;foreach(array('publish','private','draft','pending') as $s)if($q&&isset($q->$s))$n+=(int)$q->$s;return $n;}
function legacyx_reports_meta_count($type,$key,$values){$q=new WP_Query(array('post_type'=>$type,'post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_query'=>array(array('key'=>$key,'value'=>(array)$values,'compare'=>'IN'))));return (int)$q->found_posts;}
function legacyx_reports_money($v){return function_exists('legacyx_money')?legacyx_money($v):'$'.number_format((float)$v,2);}
function legacyx_reports_months($months=6){$out=array();for($i=$months-1;$i>=0;$i--){$ts=strtotime('-'.$i.' months',current_time('timestamp'));$out[date('Y-m',$ts)]=date('M Y',$ts);}return $out;}
function legacyx_reports_monthly_activity($months=6){$out=array_fill_keys(array_values(legacyx_reports_months($months)),0);foreach(legacyx_reports_months($months) as $ym=>$label){list($y,$m)=array_map('intval',explode('-',$ym));$q=new WP_Query(array('post_type'=>array('legacyx_client','legacyx_assessment','legacyx_application','legacyx_work_item','legacyx_invoice','legacyx_engagement','legacyx_appointment','legacyx_message'),'post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','date_query'=>array(array('year'=>$y,'monthnum'=>$m,'column'=>'post_date'))));$out[$label]=(int)$q->found_posts;}return $out;}
function legacyx_reports_monthly_billing($months=6){$series=array();foreach(legacyx_reports_months($months) as $ym=>$label)$series[$label]=array('billed'=>0,'paid'=>0);$ids=get_posts(array('post_type'=>'legacyx_invoice','post_status'=>'any','numberposts'=>-1,'fields'=>'ids'));foreach($ids as $id){$ym=get_the_date('Y-m',$id);if(!isset(legacyx_reports_months($months)[$ym]))continue;$label=legacyx_reports_months($months)[$ym];$series[$label]['billed']+=(float)get_post_meta($id,'_legacyx_amount',true);$series[$label]['paid']+=(float)get_post_meta($id,'_legacyx_paid_amount',true);}return $series;}
function legacyx_reports_status_breakdown($type,$key,$statuses){$out=array();foreach($statuses as $status)$out[$status]=legacyx_reports_meta_count($type,$key,array($status));return $out;}
function legacyx_render_reports_dashboard(){if(!current_user_can('legacyx_view_reports'))wp_die('You do not have access to Legacy X Firm reports.','Legacy X Firm',array('response'=>403));
 $clients=legacyx_reports_count('legacyx_client');$assess=legacyx_reports_count('legacyx_assessment');$apps=legacyx_reports_count('legacyx_application');$active_apps=legacyx_reports_meta_count('legacyx_application','_legacyx_status',array('Draft','Preparing','Ready','Submitted','Under Review','Additional Information Requested'));$approved_apps=legacyx_reports_meta_count('legacyx_application','_legacyx_status',array('Approved','Funded'));$work=legacyx_reports_count('legacyx_work_item');$open_work=legacyx_reports_meta_count('legacyx_work_item','_legacyx_work_status',array('Open','In Progress','Waiting on Client','Submitted','Under Review'));$eng=legacyx_reports_count('legacyx_engagement');$active_eng=legacyx_reports_meta_count('legacyx_engagement','_legacyx_status',array('Active','In Progress','Onboarding'));$appt=legacyx_reports_count('legacyx_appointment');$messages=legacyx_reports_count('legacyx_message');$invoices=legacyx_reports_count('legacyx_invoice');$open_invoices=legacyx_reports_meta_count('legacyx_invoice','_legacyx_status',array('Open','Partially Paid','Past Due'));
 $balance=0;$paid=0;$billed=0;$invoice_posts=get_posts(array('post_type'=>'legacyx_invoice','post_status'=>'any','numberposts'=>-1,'fields'=>'ids'));foreach($invoice_posts as $iid){$amount=(float)get_post_meta($iid,'_legacyx_amount',true);$paid_amt=(float)get_post_meta($iid,'_legacyx_paid_amount',true);$billed+=$amount;$paid+=$paid_amt;$balance+=max(0,$amount-$paid_amt);} $collection=$billed>0?round(($paid/$billed)*100):0;$approval=$apps>0?round(($approved_apps/$apps)*100):0;$activity=legacyx_reports_monthly_activity(6);$activity_max=max(array_merge(array(1),array_values($activity)));$billing=legacyx_reports_monthly_billing(6);$billmax=1;foreach($billing as $b)$billmax=max($billmax,$b['billed'],$b['paid']);$app_status=legacyx_reports_status_breakdown('legacyx_application','_legacyx_status',array('Draft','Preparing','Submitted','Under Review','Additional Information Requested','Approved','Funded','Declined'));$work_status=legacyx_reports_status_breakdown('legacyx_work_item','_legacyx_work_status',array('Open','In Progress','Waiting on Client','Submitted','Under Review','Completed'));?>
<div class="wrap legacyx-reports"><div class="legacyx-reports-hero"><div><span>LEGACY X INTELLIGENCE · PHASE 15</span><h1>Executive Intelligence</h1><p>A decision dashboard for firm growth, client delivery, capital/application activity, workflow health and recorded billing performance.</p></div><div class="legacyx-report-score"><small>Recorded Collection</small><strong><?php echo esc_html($collection);?>%</strong></div></div>
<div class="legacyx-report-metrics"><article><span>Client Relationships</span><strong><?php echo esc_html($clients);?></strong><small><?php echo esc_html($assess);?> executive assessments</small></article><article><span>Application Pipeline</span><strong><?php echo esc_html($active_apps);?></strong><small><?php echo esc_html($approval);?>% approved/funded across recorded applications</small></article><article><span>Workflow Health</span><strong><?php echo esc_html($open_work);?></strong><small><?php echo esc_html($work);?> total workflow items</small></article><article><span>Active Services</span><strong><?php echo esc_html($active_eng);?></strong><small><?php echo esc_html($eng);?> recorded engagements</small></article><article><span>Recorded Billing</span><strong><?php echo esc_html(legacyx_reports_money($billed));?></strong><small><?php echo esc_html($open_invoices);?> open billing records</small></article><article><span>Outstanding</span><strong><?php echo esc_html(legacyx_reports_money($balance));?></strong><small><?php echo esc_html(legacyx_reports_money($paid));?> recorded paid</small></article></div>
<div class="legacyx-report-grid"><section><div class="legacyx-report-head"><span>GROWTH & OPERATIONS</span><h2>Six-Month Firm Activity</h2></div><div class="legacyx-bars"><?php foreach($activity as $label=>$count):$pct=max(3,round(($count/$activity_max)*100));?><div class="legacyx-bar-row"><span><?php echo esc_html($label);?></span><div><i style="width:<?php echo esc_attr($pct);?>%"></i></div><strong><?php echo esc_html($count);?></strong></div><?php endforeach;?></div></section><aside><div class="legacyx-report-head"><span>RELATIONSHIP SIGNALS</span><h2>Client Activity</h2></div><dl><div><dt>Appointments</dt><dd><?php echo esc_html($appt);?></dd></div><div><dt>Messages</dt><dd><?php echo esc_html($messages);?></dd></div><div><dt>Applications requiring action</dt><dd><?php echo esc_html($active_apps);?></dd></div><div><dt>Open workflow items</dt><dd><?php echo esc_html($open_work);?></dd></div><div><dt>Active services</dt><dd><?php echo esc_html($active_eng);?></dd></div></dl></aside></div>
<div class="legacyx-report-grid legacyx-finance-grid"><section><div class="legacyx-report-head"><span>BILLING TREND</span><h2>Recorded Billed vs Paid</h2></div><div class="legacyx-billing-bars"><?php foreach($billing as $label=>$vals):?><div class="legacyx-billing-row"><span><?php echo esc_html($label);?></span><div class="legacyx-dual"><i class="billed" style="width:<?php echo esc_attr(max(2,round(($vals['billed']/$billmax)*100)));?>%"></i><i class="paid" style="width:<?php echo esc_attr(max(2,round(($vals['paid']/$billmax)*100)));?>%"></i></div><small><?php echo esc_html(legacyx_reports_money($vals['billed']));?> / <?php echo esc_html(legacyx_reports_money($vals['paid']));?></small></div><?php endforeach;?></div><div class="legacyx-legend"><span><i></i>Billed</span><span><i></i>Paid</span></div></section><aside><div class="legacyx-report-head"><span>FINANCIAL SIGNALS</span><h2>Recorded Billing Health</h2></div><dl><div><dt>Total billed</dt><dd><?php echo esc_html(legacyx_reports_money($billed));?></dd></div><div><dt>Total paid</dt><dd><?php echo esc_html(legacyx_reports_money($paid));?></dd></div><div><dt>Outstanding</dt><dd><?php echo esc_html(legacyx_reports_money($balance));?></dd></div><div><dt>Collection ratio</dt><dd><?php echo esc_html($collection);?>%</dd></div></dl></aside></div>
<div class="legacyx-pipeline-grid"><section><div class="legacyx-report-head"><span>CAPITAL & APPLICATIONS</span><h2>Application Pipeline</h2></div><?php foreach($app_status as $status=>$count):?><div class="legacyx-pipeline-row"><span><?php echo esc_html($status);?></span><strong><?php echo esc_html($count);?></strong></div><?php endforeach;?></section><section><div class="legacyx-report-head"><span>DELIVERY</span><h2>Workflow Pipeline</h2></div><?php foreach($work_status as $status=>$count):?><div class="legacyx-pipeline-row"><span><?php echo esc_html($status);?></span><strong><?php echo esc_html($count);?></strong></div><?php endforeach;?></section></div>
<div class="legacyx-report-note"><strong>Executive intelligence boundary</strong><p>Metrics are calculated from records currently stored inside Legacy X Firm OS. Billing figures are operational records, not audited financial statements. Application metrics do not imply lender approval, funding guarantees, investment performance, or external bureau data.</p></div></div><?php }
function legacyx_reports_styles($hook){if($hook!=='firm-os_page_legacyx-reports')return;wp_register_style('legacyx-reports',false);wp_enqueue_style('legacyx-reports');$css='.legacyx-reports{max-width:1400px;margin:24px 24px 60px 4px;color:#171512}.legacyx-reports-hero{background:#171512;color:#fff;padding:36px 40px;border-radius:4px;display:flex;justify-content:space-between;align-items:flex-end;gap:30px}.legacyx-reports-hero>div>span,.legacyx-report-head>span{font-size:11px;font-weight:800;letter-spacing:.16em;color:#f05a16}.legacyx-reports-hero h1{font:40px Georgia,serif;margin:8px 0}.legacyx-reports-hero p{color:#c9c3ba;max-width:780px}.legacyx-report-score{text-align:right}.legacyx-report-score small{display:block;color:#c9c3ba}.legacyx-report-score strong{font:40px Georgia,serif;color:#f05a16}.legacyx-report-metrics{display:grid;grid-template-columns:repeat(3,1fr);background:#fff;border:1px solid #ded8ce;margin-top:18px}.legacyx-report-metrics article{padding:24px;border-right:1px solid #ded8ce;border-bottom:1px solid #ded8ce}.legacyx-report-metrics span,.legacyx-report-metrics small{display:block;color:#746e65}.legacyx-report-metrics strong{display:block;font:30px Georgia,serif;margin:7px 0}.legacyx-report-grid{display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-top:18px}.legacyx-report-grid section,.legacyx-report-grid aside,.legacyx-pipeline-grid section,.legacyx-report-note{background:#fff;border:1px solid #ded8ce;padding:30px}.legacyx-report-head h2{font:28px Georgia,serif;margin:6px 0 24px}.legacyx-bar-row{display:grid;grid-template-columns:80px 1fr 40px;gap:12px;align-items:center;margin:15px 0}.legacyx-bar-row>div,.legacyx-dual{height:10px;background:#eee9e1}.legacyx-bar-row i{display:block;height:100%;background:#f05a16}.legacyx-bar-row strong{text-align:right}.legacyx-report-grid dl{margin:0}.legacyx-report-grid dl div{display:flex;justify-content:space-between;border-bottom:1px solid #e4dfd6;padding:15px 0}.legacyx-report-grid dt{color:#625d55}.legacyx-report-grid dd{font-weight:800}.legacyx-billing-row{display:grid;grid-template-columns:80px 1fr 160px;gap:12px;align-items:center;margin:17px 0}.legacyx-dual{position:relative;height:14px}.legacyx-dual i{display:block;height:6px;position:absolute;left:0}.legacyx-dual .billed{top:0;background:#171512}.legacyx-dual .paid{bottom:0;background:#f05a16}.legacyx-billing-row small{text-align:right;color:#746e65}.legacyx-legend{display:flex;gap:20px;margin-top:20px;color:#746e65}.legacyx-legend span{display:flex;align-items:center;gap:7px}.legacyx-legend i{width:12px;height:6px;background:#171512}.legacyx-legend span+span i{background:#f05a16}.legacyx-pipeline-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.legacyx-pipeline-row{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid #e4dfd6}.legacyx-pipeline-row strong{font-size:18px}.legacyx-report-note{margin-top:18px}.legacyx-report-note strong{font:22px Georgia,serif}.legacyx-report-note p{color:#69645d;max-width:950px}@media(max-width:900px){.legacyx-report-metrics{grid-template-columns:repeat(2,1fr)}.legacyx-report-grid,.legacyx-pipeline-grid{grid-template-columns:1fr}}@media(max-width:600px){.legacyx-report-metrics{grid-template-columns:1fr}.legacyx-reports-hero{padding:28px 24px;display:block}.legacyx-reports-hero h1{font-size:34px}.legacyx-report-score{text-align:left;margin-top:20px}.legacyx-billing-row{grid-template-columns:70px 1fr}.legacyx-billing-row small{grid-column:2;text-align:left}}';wp_add_inline_style('legacyx-reports',$css);}add_action('admin_enqueue_scripts','legacyx_reports_styles');
